import json
from pathlib import Path
from html import escape

ROOT = Path(__file__).parent
ASSETS = ROOT / "diagrams"
ASSETS.mkdir(parents=True, exist_ok=True)

def svg(name, title, nodes, edges, width=700, height=900):
    """Write a simple accessible flowchart SVG; nodes are (id, kind, text, x, y)."""
    shapes = []
    centers = {}
    for ident, kind, label, x, y in nodes:
        lines = label.split("\n")
        cx, cy = x + 145, y + 36
        centers[ident] = (cx, cy, kind)
        if kind == "terminal":
            shape = f'<rect x="{x}" y="{y}" width="290" height="72" rx="36" class="terminal"/>'
        elif kind == "io":
            shape = f'<polygon points="{x+28},{y} {x+290},{y} {x+262},{y+72} {x},{y+72}" class="io"/>'
        elif kind == "decision":
            shape = f'<polygon points="{x+145},{y} {x+290},{y+58} {x+145},{y+116} {x},{y+58}" class="decision"/>'
            cy += 4
        else:
            shape = f'<rect x="{x}" y="{y}" width="290" height="72" class="process"/>'
        text = "".join(f'<tspan x="{cx}" dy="{0 if i == 0 else 22}">{escape(line)}</tspan>' for i, line in enumerate(lines))
        shapes.append(shape + f'<text x="{cx}" y="{cy - (len(lines)-1)*11}" text-anchor="middle">{text}</text>')
    links = []
    for a, b, label, route in edges:
        ax, ay, ak = centers[a]; bx, by, bk = centers[b]
        if route == "back":
            path = f'M {ax+145} {ay} L 610 {ay} L 610 {by} L {bx+145} {by}'
            labelx, labely = 615, (ay+by)/2
        elif route == "left":
            path = f'M {ax-145} {ay} L 70 {ay} L 70 {by} L {bx-145} {by}'
            labelx, labely = 10, (ay+by)/2
        elif route == "branch_right":
            path = f'M {ax+145} {ay} L 550 {ay} L 550 {by-36} L {bx} {by-36}'
            labelx, labely = 555, (ay+by)/2
        elif route == "branch_left":
            path = f'M {ax-145} {ay} L 150 {ay} L 150 {by-36} L {bx} {by-36}'
            labelx, labely = 80, (ay+by)/2
        else:
            path = f'M {ax} {ay+36} L {bx} {by-36}'
            labelx, labely = ax+14, (ay+by)/2
        links.append(f'<path d="{path}" class="arrow" marker-end="url(#arrow)"/><text class="edge-label" x="{labelx}" y="{labely-6}">{label}</text>' if label else f'<path d="{path}" class="arrow" marker-end="url(#arrow)"/>')
    content = f'''<svg xmlns="http://www.w3.org/2000/svg" width="{width}" height="{height}" viewBox="0 0 {width} {height}" role="img" aria-labelledby="title desc">
<title id="title">{escape(title)}</title><desc id="desc">Flowchart with labeled standard flowchart symbols and directed arrows.</desc>
<defs><marker id="arrow" markerWidth="10" markerHeight="10" refX="8" refY="5" orient="auto"><path d="M0,0 L10,5 L0,10 z" fill="#263746"/></marker></defs>
<style>text{{font-family:Arial,sans-serif;font-size:18px;fill:#172b3a}}.edge-label{{font-size:16px;font-weight:bold}}.terminal{{fill:#e5f2ff;stroke:#1769aa;stroke-width:2.5}}.io{{fill:#e8f6ed;stroke:#287a45;stroke-width:2.5}}.process{{fill:#fff5d8;stroke:#9a6a00;stroke-width:2.5}}.decision{{fill:#f7e9ff;stroke:#75449a;stroke-width:2.5}}.arrow{{fill:none;stroke:#263746;stroke-width:2.5}}</style>
{''.join(links)}{''.join(shapes)}</svg>'''
    (ASSETS / name).write_text(content)

