def mcq(i, q, opts, ans, expl, source, objective, operation, diagram=None):
    rec={"id":f"FLOW-{i:03d}","question":q,"options":opts,"correctIndex":ans,"expectedAnswer":opts[ans],"explanation":expl,"source":source,"objective":objective,"operation":operation}
    if diagram: rec["stimulusAsset"] = f"diagrams/{diagram}"
    return rec

